#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAX_INPUT_LEN 1023   /* 0x3ff as in the original binary */

static void escape_string(const char *src, char *dst)
{
    while (*src) {
        switch (*src) {
            case '\\':
                *dst++ = '\\';
                *dst++ = '\\';
                break;
            case '"':
                *dst++ = '\\';
                *dst++ = '"';
                break;
            case '\n':
                *dst++ = '\\';
                *dst++ = 'n';
                break;
            case '\t':
                *dst++ = '\\';
                *dst++ = 't';
                break;
            default:
                *dst++ = *src;
                break;
        }
        src++;
    }
    *dst = '\0';
}

static void unescape_string(const char *src, char *dst)
{
    while (*src) {
        if (*src == '\\') {
            char nxt = src[1];
            if (nxt == '\0') {               /* stray back‑slash at end */
                *dst++ = '\\';
                src++;                       /* consume the back‑slash */
                continue;
            }
            switch (nxt) {
                case '\\':
                    *dst++ = '\\';
                    src += 2;
                    continue;
                case '"':
                    *dst++ = '"';
                    src += 2;
                    continue;
                case 'n':
                    *dst++ = '\n';
                    src += 2;
                    continue;
                case 't':
                    *dst++ = '\t';
                    src += 2;
                    continue;
                default:
                    /* Unknown escape – keep the back‑slash literally */
                    *dst++ = '\\';
                    src++;   /* fall through to copy the next char */
                    break;
            }
        }
        *dst++ = *src++;
    }
    *dst = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *input = argv[2];
    bool do_escape;
    if (strcmp(mode, "escape") == 0) {
        do_escape = true;
    } else if (strcmp(mode, "unescape") == 0) {
        do_escape = false;
    } else {
        puts("INVALID_MODE");
        return 0;
    }

    size_t len = strlen(input);
    if (len > MAX_INPUT_LEN) {
        puts("INVALID");
        return 0;
    }

    char *out_buf = malloc(2 * MAX_INPUT_LEN + 2);
    if (!out_buf) {
        perror("malloc");
        return 1;
    }

    if (do_escape) {
        escape_string(input, out_buf);
    } else {
        unescape_string(input, out_buf);
    }

    puts(out_buf);
    free(out_buf);
    return 0;
}
